package com.votesecure.onlinevoting.repository;import com.votesecure.onlinevoting.model.Vote;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Query;import java.util.*;public interface VoteRepository extends JpaRepository<Vote,Long>{Optional<Vote> findByVoterId(Long voterId);@Query("select v.candidate.id, v.candidate.fullName, v.candidate.partyName, count(v.id) from Vote v group by v.candidate.id,v.candidate.fullName,v.candidate.partyName order by count(v.id) desc") List<Object[]> counts();}
